function cm(m,t){const A=nm(t.ps[m.a]),B=nm(t.ps[m.b]),d=m.sa-m.sb,k=Math.abs(d),hi=Math.max(m.sa,m.sb),lo=Math.min(m.sa,m.sb);if(!d)return"Stalemate vibes. Both managers nodded like 'yeah... we good'.";const w=d>0?A:B,l=d>0?B:A;return k>=3?`${w} cooked ${l} ${hi}-${lo}. Someone check on them.`:k==1?`${w} snatch it ${hi}-${lo}. ${l} are gonna feel that one for a WEEK.`:`${w} take it ${hi}-${lo}. ${l} need a hug.`}
function boom(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const c=document.createElement('canvas');c.style.cssText='position:fixed;inset:0;width:100%;height:100%;pointer-events:none;z-index:9';c.width=innerWidth;c.height=innerHeight;document.body.appendChild(c);const x=c.getContext('2d'),P=[...Array(130)].map(()=>({x:c.width/2,y:c.height*.4,vx:(Math.random()-.5)*16,vy:-Math.random()*14-4,s:4+Math.random()*5,c:Math.random()<.6?'#ffc83d':'#fff',r:Math.random()*6}));let f=0;(function l(){x.clearRect(0,0,c.width,c.height);P.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.35;p.r+=.2;x.fillStyle=p.c;x.save();x.translate(p.x,p.y);x.rotate(p.r);x.fillRect(-p.s/2,-p.s/2,p.s,p.s*.6);x.restore()});if(++f<150)requestAnimationFrame(l);else c.remove()})()}
