addp:()=>{const n=$('#pn').value.trim(),r=5;if(n&&!N.ps.find(p=>p.n.toLowerCase()===n.toLowerCase())){N.ps.push({n,r});N.r=r}render()},
sp:d=>{const p=S.saved[d.i];if(!N.ps.find(x=>x.n===p.n))N.ps.push({...p});render()},dp:d=>{N.ps.splice(d.i,1);render()},
fmt:d=>{N.fmt=+d.f;render()},asg:()=>{N.assign=!N.assign;render()},tp:d=>{const i=N.pool.indexOf(d.n);i<0?N.pool.push(d.n):N.pool.splice(i,1);render()},
