function rivalHtml(){const R=rivalData();if(!R.length)return'';const close=[...R].sort((a,b)=>Math.abs(a.aw-a.bw)-Math.abs(b.aw-b.bw)||b.m-a.m)[0],one=[...R].sort((a,b)=>Math.abs(b.aw-b.bw)-Math.abs(a.aw-a.bw))[0];return `<h3 class="h">Rivalries</h3><div class="g">${R.slice(0,4).map((r,i)=>{const total=Math.max(1,r.aw+r.bw),wa=r.aw/total*100;return `<div class="card rival ${AN?'in':''}" style="--i:${i}"><div class="versus">VS</div><div class="mu sm">${i===0?'🔥 MOST PLAYED':r===close?'⚔️ CLOSEST RIVALRY':r===one?'💀 MOST ONE-SIDED':'RIVALRY'}</div><div class="big2">${esc(r.a)} vs ${esc(r.b)}</div><div class="rival-line"><i style="width:${wa}%"></i><i style="width:${100-wa}%"></i></div><div class="row sm"><b>${r.aw} wins</b><span class="sp mu">${r.d} draws · ${r.m} games</span><b>${r.bw} wins</b></div><div class="mu sm" style="margin-top:6px">Goals ${r.ag}–${r.bg}</div></div>`}).join('')}</div>`}
function records(){let games=[],P=allCareer();S.tours.forEach(t=>done(t).forEach(m=>games.push({t,m,a:t.ps[m.a].n,b:t.ps[m.b].n,sum:m.sa+m.sb,margin:Math.abs(m.sa-m.sb)})));if(!games.length)return'';const big=[...games].sort((x,y)=>y.margin-x.margin||y.sum-x.sum)[0],high=[...games].sort((x,y)=>y.sum-x.sum)[0],tg=[...P].sort((a,b)=>b.gf-a.gf)[0],tw=[...P].sort((a,b)=>b.w-a.w)[0],tt=[...P].sort((a,b)=>b.titles-a.titles)[0],cs=[...P].sort((a,b)=>b.cs-a.cs)[0];const rec=[['💥','Biggest Win',`${big.a} ${big.m.sa}–${big.m.sb} ${big.b}`],['🎆','Highest Scoring',`${high.a} ${high.m.sa}–${high.m.sb} ${high.b}`],['⚽','Goal King',`${tg.n} · ${tg.gf} goals`],['👑','Most Titles',`${tt.n} · ${tt.titles}`],['✅','Most Wins',`${tw.n} · ${tw.w}`],['🧱','Clean Sheet King',`${cs.n} · ${cs.cs}`]];return `<h3 class="h">Records</h3><div class="rec-grid">${rec.map((r,i)=>`<div class="card record ${AN?'in':''}" style="--i:${i}"><div class="ri">${r[0]}</div><div class="rlb">${r[1]}</div><div class="rv">${esc(r[2])}</div></div>`).join('')}</div>`}
function story(t){if(!t||t.champ==null)return'';const ms=done(t),R=pstats(t),ch=t.ps[t.champ],cr=R[t.champ],big=[...ms].sort((a,b)=>Math.abs(b.sa-b.sb)-Math.abs(a.sa-a.sb))[0],high=[...ms].sort((a,b)=>(b.sa+b.sb)-(a.sa+a.sb))[0];let steps=[];if(ms[0])steps.push(['Opening whistle',`${L(ms[0],t)} opened the tournament.`]);if(big)steps.push(['Statement result',`${L(big,t)} was the biggest winning margin.`]);if(high&&high!==big)steps.push(['Goal fest',`${L(high,t)} produced the most goals.`]);if(t.final)steps.push(['Grand Final',`${L(t.final,t)}${t.final.pen?' · decided on penalties':''}.`]);steps.push(['Champion crowned',`${ch.n} lifted the trophy with ${cr.W} wins and ${cr.F} goals scored.`]);return `<div class="card story"><div class="mu sm">THE STORY OF ${esc(t.name).toUpperCase()}</div>${steps.map(x=>`<div class="story-step"><b>${esc(x[0])}</b><small>${esc(x[1])}</small></div>`).join('')}</div>`}
function ceremony(t){if(!t||lv()==='off')return;const o=document.createElement('div');o.className='oc';o.innerHTML=`<div class="ocbox"><div class="octag">WELCOME TO</div><div class="octitle">${esc(t.name)}</div><div class="mu">${t.ps.length} PLAYERS · ${t.rounds.flat().length} LEAGUE MATCHES</div><div class="ocplayers">${t.ps.map((p,i)=>`<span class="ocp" style="--i:${i}">${esc(p.n)}</span>`).join('')}</div><div class="ocgo">LET THE GAMES BEGIN</div><button class="cskip" style="pointer-events:auto" data-ocskip>Skip ▸</button></div>`;document.body.appendChild(o);const end=()=>{if(o.isConnected)o.remove()};o.querySelector('[data-ocskip]').onclick=end;setTimeout(end,3600)}
function matchIntro(d,next){const t=T(),m=fm(d.m);if(!t||!m||m.id==='F'||lv()==='off')return next();const A=t.ps[m.a],B=t.ps[m.b],o=document.createElement('div');o.className='mintro';o.innerHTML=`<div class="mirow"><div class="miteam a"><span class="av" style="--h:${hue(A.n)}">${esc(A.n[0].toUpperCase())}</span><strong>${esc(A.n)}</strong><small>${esc(m.ta||A.team||'')}</small></div><div class="mivs">VS</div><div class="miteam b"><span class="av" style="--h:${hue(B.n)}">${esc(B.n[0].toUpperCase())}</span><strong>${esc(B.n)}</strong><small>${esc(m.tb||B.team||'')}</small></div></div>`;document.body.appendChild(o);setTimeout(()=>{o.remove();next()},1250)}
function goalTake(type,name,score){if(lv()==='off')return;const o=document.createElement('div');o.className='gtake '+(type.cls||'');o.innerHTML=`<div><small>${esc(type.kicker||'PITCH ROYALE')}</small><b>${esc(type.title)}</b><span>${esc(name)} · ${esc(score)}</span></div>`;document.body.appendChild(o);setTimeout(()=>o.remove(),980)}
function atmosphere(){document.body.classList.remove('atm-tight','atm-draw','atm-dom','atm-final');if(V.v!=='tour')return;const t=T(),m=t&&[...t.rounds.flat(),t.final].filter(Boolean).find(x=>x.st==='live');if(!m)return;const d=Math.abs(m.sa-m.sb);document.body.classList.add(m.id==='F'?'atm-final':d===0?'atm-draw':d===1?'atm-tight':'atm-dom')}
function addTV(){const tv=$('#tv'),t=T();if(!tv||!t)return;const b=tv.querySelector('.tvb');if(!b||b.querySelector('.broadcast-strip'))return;const tb=table(t),played=done(t),goals=played.reduce((s,m)=>s+m.sa+m.sb,0),live=[...t.rounds.flat(),t.final].filter(Boolean).find(m=>m.st==='live');const top=tb[0];b.insertAdjacentHTML('beforeend',`<div class="broadcast-strip"><div><span class="mu sm">LEADER</span><b>${top?esc(t.ps[top.i].n):'–'}</b></div><div><span class="mu sm">TOURNAMENT GOALS</span><b>${goals}</b></div><div><span class="mu sm">STATUS</span><b>${live?'● LIVE':'MATCH NIGHT'}</b></div></div><div class="broadcast-ticker"><span>${tb.map((r,i)=>`${i+1}. ${esc(t.ps[r.i].n)} ${r.Pt}pts · `).join('')}${tb.map((r,i)=>`${i+1}. ${esc(t.ps[r.i].n)} ${r.Pt}pts · `).join('')}</span></div>`)}

