/* v40 continues inside the same upgrade scope so it can extend the career helpers above. */
const esc40=s=>E(String(s==null?'':s));
const k40=n=>String(n||'').trim().toLowerCase();
function career40(){try{return allCareer()}catch(e){return[]}}
function ratingMap40(){const z={};career40().forEach(p=>z[k40(p.n)]=p.rating);return z}
function archetype40(p){
 if(p.titles>=3)return['👑','Serial Winner'];
 if(p.cs>=Math.max(3,Math.round(p.m*.3)))return['🧱','The Wall'];
 if(p.gf>=Math.max(12,p.m*2.2))return['🎯','The Finisher'];
 if(p.w>=8&&p.m&&p.w/p.m>=.7)return['🔥','Mr. Consistent'];
 if(p.finals>=2&&p.titles===0)return['🥶','The Nearly Man'];
 if((p.form||[]).slice(-3).filter(x=>x==='W').length===3)return['⚡','On Fire'];
 return['🎭','Wild Card'];
}
function momentum40(p){const f=(p.form||[]).slice(-5),v=f.reduce((s,x)=>s+(x==='W'?2:x==='D'?1:0),0),n=Math.max(1,Math.min(5,Math.round(v/2)));return {n,t:v>=8?'Hot form':v<=2?'Cold spell':'Building momentum'}}
function legacy40(p){return Math.round(p.titles*140+p.finals*35+p.w*11+p.gf*3+p.cs*7+Math.max(0,p.rating-75)*18)}
function power40(){return career40().map(p=>{const f=(p.form||[]).slice(-5),pts=f.reduce((s,x)=>s+(x==='W'?3:x==='D'?1:0),0),score=p.rating+pts*1.7+(f[0]==='W'?1:0);return {...p,score}}).sort((a,b)=>b.score-a.score)}
function powerHtml40(){const P=power40();if(!P.length)return'';return `<h3 class="h">Power Ranking</h3><div class="card"><div class="mu sm" style="margin-bottom:8px">Who is hottest right now — separate from long-term OVR.</div><div class="prank">${P.slice(0,6).map((p,i)=>{const prev=[...P].sort((a,b)=>b.rating-a.rating).findIndex(x=>k40(x.n)===k40(p.n)),d=prev-i,tr=d>0?'up':d<0?'dn':'eq',sy=d>0?'↑'+d:d<0?'↓'+Math.abs(d):'—';return `<div class="prrow"><span class="num">${i+1}</span><b>${esc40(p.n)}</b><span class="trend ${tr}">${sy}</span><span class="pt">${p.rating}</span></div>`}).join('')}</div></div>`}
function legacyHtml40(){const P=career40().sort((a,b)=>legacy40(b)-legacy40(a));if(!P.length)return'';const p=P[0];return `<h3 class="h">Legacy</h3><div class="card legacy"><div class="mu sm">ALL-TIME LEGACY LEADER</div><div class="ls">${legacy40(p)}</div><div class="big2">👑 ${esc40(p.n)}</div><small>Titles, finals, wins, goals, clean sheets and OVR combined into one prestige score.</small></div>`}
function prediction40(m,t){if(!m||!t||m.st!=='up')return null;const rm=ratingMap40(),A=t.ps[m.a],B=t.ps[m.b],ra=rm[k40(A.n)]||75,rb=rm[k40(B.n)]||75,d=ra-rb;let draw=Math.max(12,22-Math.abs(d)*.45),a=50+d*1.8-draw/2;a=Math.max(12,Math.min(76,a));let b=100-draw-a;if(b<12){a-=12-b;b=12}const fav=a>b?A:B,und=a>b?B:A,fp=Math.round(Math.max(a,b)),up=Math.round(Math.min(a,b)),dp=Math.round(draw);let line=Math.abs(d)<2?`${A.n} and ${B.n} are almost impossible to split.`:`${fav.n} enters as the ${Math.abs(d)>=7?'clear':'slight'} favourite.`;const h=h2h(A.n,B.n);if(h&&h.n>=3){const aw=k40(A.n)<k40(B.n)?h.w1:h.w2;line+=` They have met ${h.n} times before.`}return {a:Math.round(a),b:Math.round(b),d:dp,line,und:und.n,ra,rb}}
function predHtml40(m,t){const p=prediction40(m,t);if(!p)return'';const A=t.ps[m.a],B=t.ps[m.b],ud=Math.abs(p.ra-p.rb)>=5?`<span class="story-tag ud">🐺 ${esc40(p.und)} · Underdog</span>`:'';return `<div class="pred">${ud}<div class="prednums"><span>${esc40(A.n)} ${p.a}%</span><span>Draw ${p.d}%</span><span>${p.b}% ${esc40(B.n)}</span></div><div class="predbar"><i class="pa" style="width:${p.a}%"></i><i class="pd" style="width:${p.d}%"></i><i class="pb2" style="width:${p.b}%"></i></div><div class="predline">${esc40(p.line)}</div></div>`}
const mc40=mc;mc=function(m,t,i){let h=mc40(m,t,i);if(m&&m.st==='up'){const x=predHtml40(m,t),pos=h.lastIndexOf('</div>');if(pos>0)h=h.slice(0,pos)+x+h.slice(pos)}return h};
function enhanceCards40(html){return html.replace(/(<div class="card pcard[\s\S]*?<div class="pname">)([^<]+)(<\/div>)([\s\S]*?)(<div class="mini4 three">)/g,(all,a,name,c,mid,e)=>{const p=career40().find(x=>k40(x.n)===k40(name.replace(/&amp;/g,'&')));if(!p)return all;const ar=archetype40(p),mo=momentum40(p);return a+name+c+mid+`<div class="arch">${ar[0]} ${ar[1]}</div><div class="mom">${[0,1,2,3,4].map(i=>`<i class="${i<mo.n?'on':''}"></i>`).join('')}</div><div class="momtxt">${mo.t}</div>`+e})}
const pc40=playerCards;playerCards=function(){return enhanceCards40(pc40())};
function rivalryStories40(){const R=rivalData();if(!R.length)return'';return `<div class="card" style="margin-top:10px"><div class="mu sm">RIVALRY STORYLINES</div>${R.slice(0,5).map(r=>{let s;if(r.m>=5&&Math.abs(r.aw-r.bw)<=1)s=`${r.a} and ${r.b} are basically inseparable: ${r.aw}-${r.bw} in wins across ${r.m} meetings.`;else if(Math.abs(r.aw-r.bw)>=3)s=`${r.aw>r.bw?r.a:r.b} has owned this rivalry lately, leading ${Math.max(r.aw,r.bw)}-${Math.min(r.aw,r.bw)}.`;else if(r.ag+r.bg>=20)s=`Whenever ${r.a} meets ${r.b}, goals follow: ${r.ag+r.bg} in ${r.m} games.`;else s=`${r.a} vs ${r.b}: ${r.m} meetings and ${r.ag+r.bg} total goals.`;return `<div class="rr"><b>${esc40(r.a)} vs ${esc40(r.b)}</b><div class="mu sm">${esc40(s)}</div></div>`}).join('')}</div>`}
const rh40=rivalHtml;rivalHtml=function(){return rh40()+rivalryStories40()};
function trophy40(t){if(!t)return['🏆','Champions Cup'];const f=t.fmt||1,n=t.ps.length;if(n===2)return['⚔️','Duel Crown'];if(f>=4)return['🛡️','Endurance Shield'];if(n>=6)return['👑','Royal Champions Cup'];if(n<=4)return['🏆','Elite Cup'];return['🏆','Champions Cup']}
function formArr40(t,i){return t.rounds.flat().filter(m=>m.st==='ft'&&(m.a===i||m.b===i)).sort((a,b)=>(a.t||0)-(b.t||0)).slice(-5).map(m=>{const f=m.a===i?m.sa:m.sb,a=m.a===i?m.sb:m.sa;return f>a?'W':f<a?'L':'D'})}
function road40(t){if(!t||!t.final)return'';const F=t.final,tt=trophy40(t);const side=i=>`<div class="roadp"><span class="av" style="--h:${hue(t.ps[i].n)}">${esc40(t.ps[i].n[0].toUpperCase())}</span><b style="display:block;margin-top:6px">${esc40(t.ps[i].n)}</b><div class="roadform">${formArr40(t,i).map(x=>`<i class="${x}">${x}</i>`).join('')||'<span class="mu sm">No form yet</span>'}</div></div>`;return `<h3 class="h">Road to the Final</h3><div class="card"><div style="text-align:center;margin-bottom:10px"><span class="trophytype">${tt[0]} ${tt[1]}</span></div><div class="road">${side(F.a)}<div class="roadvs">VS</div>${side(F.b)}</div></div>`}
function awards40(t){if(!t||t.champ==null)return'';const ps=pstats(t),ms=done(t);if(!ms.length)return'';const mvp=[...ps.map((p,i)=>({i,s:p.Pt*4+p.F*1.5+(i===t.champ?12:0)+(t.final&&(t.final.a===i||t.final.b===i)?3:0)}))].sort((a,b)=>b.s-a.s)[0];const mot=[...ms].sort((a,b)=>{const sa=(a.sa+a.sb)*2+(Math.min(a.sa,a.sb))*2+(a.id==='F'?8:0)+(Math.abs(a.sa-a.sb)<=1?4:0),sb=(b.sa+b.sb)*2+(Math.min(b.sa,b.sb))*2+(b.id==='F'?8:0)+(Math.abs(b.sa-b.sb)<=1?4:0);return sb-sa})[0];return `<h3 class="h">Tournament Awards</h3><div class="awardgrid"><div class="card award"><div class="ico">⭐</div><div class="mu sm">TOURNAMENT MVP</div><div class="an">${esc40(t.ps[mvp.i].n)}</div><div class="mu sm">${ps[mvp.i].W} wins · ${ps[mvp.i].F} goals</div></div><div class="card award"><div class="ico">🎬</div><div class="mu sm">MATCH OF THE TOURNAMENT</div><div class="an">${esc40(L(mot,t))}</div><div class="mu sm">Chosen for drama, goals and importance.</div></div></div>`}
const vt40=vTour;vTour=function(t){let h=vt40(t);if(t&&t.final&&(V.tab==='fin'||V.tab==='fix'))h+=road40(t);if(t&&t.champ!=null&&(V.tab==='his'||V.tab==='fin'))h+=awards40(t);return h};
const vs40=vStats;vStats=function(){let h=vs40();if(!career40().length)return h;return h+powerHtml40()+legacyHtml40()};
const vh40=vHof;vHof=function(){const P=career40().sort((a,b)=>legacy40(b)-legacy40(a));const shelf=S.tours.filter(t=>t.champ!=null).slice(-8).reverse();return vh40()+(P.length?`<h3 class="h">Legacy Board</h3><div class="g">${P.slice(0,4).map((p,i)=>`<div class="card legacy"><div class="mu sm">#${i+1} LEGACY</div><div class="ls">${legacy40(p)}</div><b>${esc40(p.n)}</b></div>`).join('')}</div>`:'')+(shelf.length?`<h3 class="h">Trophy Cabinet</h3><div class="g">${shelf.map(t=>{const tr=trophy40(t);return `<div class="card"><div style="font-size:30px">${tr[0]}</div><b>${esc40(tr[1])}</b><div class="mu sm">${esc40(t.name)}</div><div class="gold-t">${esc40(t.ps[t.champ].n)}</div></div>`}).join('')}</div>`:'')};
