function postMatch40(t,m,before){if(!t||!m||m.st!=='ft'||lv()==='off')return;const A=t.ps[m.a],B=t.ps[m.b],after=ratingMap40(),wa=after[k40(A.n)]||75,wb=after[k40(B.n)]||75,da=wa-(before[k40(A.n)]||wa),db=wb-(before[k40(B.n)]||wb),fmt=n=>(n>=0?'+':'')+n.toFixed(1);toast(`OVR · ${A.n} ${fmt(da)} · ${B.n} ${fmt(db)}`)}
function upset40(t,m,before){if(!t||!m||m.st!=='ft')return;const A=t.ps[m.a],B=t.ps[m.b],ra=before[k40(A.n)]||75,rb=before[k40(B.n)]||75;if(Math.abs(ra-rb)<6)return;const under=ra<rb?{p:A,s:m.sa,o:m.sb,r:ra,or:rb}:{p:B,s:m.sb,o:m.sa,r:rb,or:ra};if(under.s<=under.o&&!(under.s===under.o&&m.pen))return;const o=overlay40(`<div><b>🚨 MASSIVE UPSET<small>${esc40(under.p.n)} · ${Math.round(under.r)} OVR beats ${Math.round(under.or)} OVR favourite</small></b></div>`,'upset40');m.upset=1;save();setTimeout(()=>o.remove(),1850)}
const ft40=ACT.ft;ACT.ft=function(d,b){const before=ratingMap40(),t=T();ft40(d,b);const m=fm(d.m);if(m&&m.st==='ft')setTimeout(()=>{upset40(t,m,before);postMatch40(t,m,before)},120)};
